{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows recent pessimism (e.g., sentiment < 0.00).",
    "Reduce forecast overshoots following sharp price spikes by applying a 10-15% dampening factor to the immediate next period.",
    "Apply mean reversion bias: if forecast deviates > ±15% from recent 7-day average, adjust toward the average.",
    "Increase forecast sensitivity to sentiment when historical volatility is high (e.g., recent 30-day std > 5.0).",
    "Delay forecast adjustments for 1-2 periods if sentiment is neutral or slowly evolving (e.g., sentiment < 0.25 and stable for 3+ days).",
    "For long-term horizons (>14 days), reduce forecast volatility by smoothing with a 3-period moving average if sentiment is weak or flat."
  ]
}
